  var sciPanel = document.querySelector('[data-testid="sci-panel"]');
""")
rep("""      state.value = -state.value;
      state.operand = true;
      if (state.groupTok !== null) {
        state.tokens[state.groupTok] = state.tokens[state.groupTok] === '(' ? '-(' : '(';
      }""","""      state.value = -state.value;
      state.operand = true;
      if (state.groupTok !== null) {
        var t = state.tokens[state.groupTok];
        state.tokens[state.groupTok] = t.charAt(0) === '-' ? t.slice(1) : '-' + t;
      }""")
rep("""  // Immediate execution,""","""  // √x, x² and 1/x act on the shown number at once, and the result becomes
  // the next operand. On the tape the operand is written as one token, such
  // as √(9) or sqr((2 + 7)), which groupTok then points at.
  var FUNCTIONS = {
    sqrt: { name: '√', apply: Math.sqrt },
    square: { name: 'sqr', apply: function (x) { return x * x; } },
    recip: { name: '1/', apply: function (x) { return 1 / x; } }
  };

  function applyFunction(key) {
    if (state.error) return;
    var fn = FUNCTIONS[key];
    var n = currentNumber();
    var text;
    if (state.groupTok !== null) {
      text = joinTokens(state.tokens.slice(state.groupTok));
      state.tokens.length = state.groupTok;
    } else {
      text = formatValue(n);
    }
    state.entry = null;
    setResult(fn.apply(n));
    if (state.error) return;
    state.operand = true;
    state.groupTok = state.tokens.length;
    state.tokens.push(fn.name + '(' + text + ')');
  }

  // Immediate execution,""")
