    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
    else if (btn.hasAttribute('data-fn')) applyFunction(btn.getAttribute('data-fn'));""")
rep("""      else if (action === 'mc') memoryClear();
""","""      else if (action === 'mc') memoryClear();
      else if (action === 'sci') toggleSciPanel();
""")
