  'MC':'mc','MR':'mr','M+':'mplus','√':'sqrt','²':'square','⅟':'recip','S':'sci' };
let fails = 0, n = 0;
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  const load = async () => { await page.goto(url); };
  const press = async seq => { for (const t of seq.split(' ').filter(Boolean)) await page.click(`[data-testid="key-${K[t] || t}"]`); };
  const disp = () => page.textContent('[data-testid="calc-display"]');
  const check = (name, got, want) => { n++; if (got !== want) { fails++; console.log(`FAIL ${name}: got ${JSON.stringify(got)} want ${JSON.stringify(want)}`); } };
  const t = async (seq, want, sci) => { await load(); if (sci) await press('S'); await press(seq); check(seq, await disp(), want); };

  // basics, left-to-right
  await t('1 2 + 7 =', '19');
  await t('2 + 3 * 4 =', '20');
  await t('9 - 1 2 =', '-3');
  await t('7 / 2 =', '3.5');
  await t('0 . 1 + 0 . 2 =', '0.3');
  await t('. 5', '0.5');
  await t('1 . 2 . 3', '1.23');
  await t('2 + * 3 =', '6');
  await t('1 / 3 =', '0.3333333333');
  await t('1 / 3 * 3 =', '1');
  await t('9 9 9 9 9 9 9 9 9 9 * 1 0 =', '1e+11');
  await t('1 / 0 =', 'Error');
  await t('1 / 0 = 5 +', 'Error');
  await t('1 / 0 = C 5', '5');
  // sign
  await t('5 ±', '-5');
  await t('± 5', '-5');
  await t('2 + 3 = ±', '-5');
  // parens
  await t('2 * ( 3 + 4 ) =', '14');
  await t('2 ( 3 ) =', '6');
  await t('( 1 + 2 =', '3');
  await t('( ( 2 + 3 ) * 2 ) - 1 =', '9');
  // memory
  await load(); await press('5 M+'); check('mem indicator', await page.getAttribute('[data-testid="mem-indicator"]', 'data-active'), 'true');
  await press('3 M+ C MR'); check('MR', await disp(), '8');
  await press('MC'); check('mem cleared', await page.getAttribute('[data-testid="mem-indicator"]', 'data-active'), 'false');
  // tape
  await load(); await press('2 * ( 3 + 4 ) ='); await press('1 0 ± + 1 =');
  const exprs = await page.$$eval('[data-testid="tape-expr"]', e => e.map(x => x.textContent));
  check('tape', JSON.stringify(exprs), JSON.stringify(['-10 + 1', '2 × (3 + 4)']));
  await page.click('[data-testid="tape-clear"]');
  check('tape clear', await page.$$eval('[data-testid="tape-row"]', e => e.length), 0);

  // keyboard
  const typeKeys = async keys => { for (const k of keys) await page.keyboard.press(k); };
  await load(); await typeKeys(['1','2','.','5','+','3','Enter']); check('kbd enter', await disp(), '15.5');
  await load(); await typeKeys(['8','-','2','*','3','/','9','=']); check('kbd ops =', await disp(), '2');
  await typeKeys(['Escape']); check('kbd escape', await disp(), '0');
  // Enter after clicking a button must not also click it
  await load(); await press('7 + 1'); await page.keyboard.press('Enter'); check('kbd enter focused btn', await disp(), '8');
  check('kbd enter no double', await page.$$eval('[data-testid="tape-row"]', e => e.length), 1);

  // scientific panel
  await load();
  check('sci hidden', await page.isVisible('[data-testid="key-sqrt"]'), false);
  await press('S');
  for (const k of ['sqrt','square','recip']) check('sci visible ' + k, await page.isVisible(`[data-testid="key-${k}"]`), true);
  await press('S'); check('sci hides again', await page.isVisible('[data-testid="key-sqrt"]'), false);
  await t('9 √', '3', true);
  await t('4 ²', '16', true);
  await t('4 ⅟', '0.25', true);
  await t('0 ⅟', 'Error', true);
  await t('4 ± √', 'Error', true);
  await t('9 √ + 1 =', '4', true);
  await t('9 √ 5', '5', true);
  await t('2 + 9 √ =', '5', true);
  await t('2 + 3 = ²', '25', true);
  await t('( 2 + 7 ) √ * 2 =', '6', true);
  await t('2 √ ²', '2', true);
  await t('3 √ ± ²', '3', true);
  await t('1 0 ⅟ M+ C MR', '0.1', true);
  await load(); await press('S'); await press('2 + 9 √ ='); await press('( 1 + 3 ) √ ± ² =');
  const sciTape = await page.$$eval('[data-testid="tape-expr"]', e => e.map(x => x.textContent));
  check('sci tape', JSON.stringify(sciTape), JSON.stringify(['2 + √(9)']));
  await press('5 + 3 ²'); await page.keyboard.press('Enter');
  check('sci tape 2', await page.textContent('[data-testid="tape-expr"]'), '5 + sqr(3)');
  await load(); await press('S ( 1 + 3 ) √ ± + 1 =');
  check('sci tape group', await page.textContent('[data-testid="tape-expr"]'), '-√((1 + 3)) + 1');
  check('sci tape group val', await disp(), '-1');

  // phone width: no horizontal scroll
  await page.setViewportSize({ width: 400, height: 900 });
  await load(); await press('S');
  check('no h-scroll', await page.evaluate(() => document.documentElement.scrollWidth <= 400), true);
  await page.screenshot({ path: __dirname + '/shot.png', fullPage: true });

  check('no page errors', errors.join('|'), '');
  console.log(`${n - fails}/${n} passed`);
  await browser.close();
  process.exit(fails ? 1 : 0);
})();
EOF
